INSERT INTO `book` (`id`, `title`, `author`, `binding`, `publisher`, `price`, `pages`, `pubdate`, `isbn`, `summary`, `image`, `status`, `create_time`) VALUES (46, '剑指Offer', '何海涛', '平装', '电子工业出版社', '59.00', 316, '2012-01-01', '9787121167904', '收录60余道经典面试算法题，附详细解题思路，是程序员面试备考必备书目。', 'sword_offer.jpg', 1, 1701966044);
INSERT INTO `book` (`id`, `title`, `author`, `binding`, `publisher`, `price`, `pages`, `pubdate`, `isbn`, `summary`, `image`, `status`, `create_time`) VALUES (47, '算法图解', '阿迪蒂亚·Y·巴尔加瓦', '平装', '人民邮电出版社', '49.00', 200, '2017-03-01', '9787115428288', '以直观图解方式讲解常用算法，包括二分查找、排序、图算法等，轻松易懂。', 'grokking_algorithms.jpg', 2, 1702543590);
INSERT INTO `book` (`id`, `title`, `author`, `binding`, `publisher`, `price`, `pages`, `pubdate`, `isbn`, `summary`, `image`, `status`, `create_time`) VALUES (48, '机器学习', '周志华', '平装', '清华大学出版社', '88.00', 438, '2016-01-01', '9787302423287', '系统介绍机器学习的主要方法和理论，由浅入深，兼顾广度与深度，俗称\"西瓜书\"。', 'ml_zhihua.jpg', 1, 1702905137);
INSERT INTO `book` (`id`, `title`, `author`, `binding`, `publisher`, `price`, `pages`, `pubdate`, `isbn`, `summary`, `image`, `status`, `create_time`) VALUES (49, '统计学习方法', '李航', '平装', '清华大学出版社', '59.00', 285, '2019-05-01', '9787302517276', '系统讲解统计机器学习的理论与方法，数学推导严谨，是机器学习进阶必读书。', 'statistical_learning.jpg', 1, 1703241423);
INSERT INTO `book` (`id`, `title`, `author`, `binding`, `publisher`, `price`, `pages`, `pubdate`, `isbn`, `summary`, `image`, `status`, `create_time`) VALUES (50, '深度学习', '伊恩·古德费洛', '精装', '人民邮电出版社', '168.00', 753, '2017-07-01', '9787115461476', '深度学习领域的权威教材，由领域顶级专家编写，全面覆盖理论基础与前沿进展。', 'deep_learning.jpg', 1, 1703775829);
